class Solution:
    def canAliceWin(self, nums: List[int]) -> bool:
        s = sum(x for x in nums if x < 10)
        return 2 * max(s, sum(nums) - s) > sum(nums)

c.cpp:
class Solution {
public:
    bool canAliceWin(vector<int>& nums) {
        int total = accumulate(nums.begin(), nums.end(), 0), s = 0;
        for (int x : nums) if (x < 10) s += x;
        return 2 * max(s, total - s) > total;
    }
};

c.java:
class Solution {
    public boolean canAliceWin(int[] nums) {
        int total = 0, s = 0;
        for (int x : nums) { total += x; if (x < 10) s += x; }
        return 2 * Math.max(s, total - s) > total;
    }
}

